<template>
  <section>
    <el-alert title="这里只记录已发生的支出和付款，不会发起实际付款。" type="info" :closable="false" />
    <div class="toolbar"><el-select v-model="status" placeholder="全部状态" clearable @change="load"><el-option label="未付款" value="UNPAID" /><el-option label="已付款" value="PAID" /><el-option label="已取消" value="CANCELLED" /></el-select><el-button type="primary" @click="createOpen = true">新增支出</el-button></div>
    <el-table v-loading="loading" :data="rows" empty-text="暂无支出记录">
      <el-table-column label="楼栋" prop="building.name" /><el-table-column label="分类" prop="category" /><el-table-column label="说明" prop="description" /><el-table-column label="金额（元）"><template #default="{ row }">{{ (row.amount / 100).toFixed(2) }}</template></el-table-column><el-table-column label="来源"><template #default="{ row }">{{ row.sourceReference || row.publicUtilityBillId }}</template></el-table-column><el-table-column label="状态"><template #default="{ row }">{{ row.cancelledAt ? '已取消' : row.payment ? '已付款' : '未付款' }}</template></el-table-column><el-table-column label="付款日期"><template #default="{ row }">{{ row.payment?.paidDate?.slice(0, 10) || '—' }}</template></el-table-column><el-table-column label="付款凭证"><template #default="{ row }">{{ row.payment?.evidence || '—' }}</template></el-table-column><el-table-column label="操作" min-width="200"><template #default="{ row }"><el-button link type="primary" @click="openDetails(row as Expense)">详情</el-button><template v-if="!row.payment && !row.cancelledAt"><el-button link type="primary" @click="openEdit(row as Expense)">更正</el-button><el-button link type="danger" @click="openCancel(row as Expense)">取消支出</el-button><el-button link type="primary" @click="openPayment(row as Expense)">记录付款</el-button></template></template></el-table-column>
    </el-table>
    <el-dialog v-model="detailsOpen" title="支出详情" width="min(520px, 95vw)">
      <el-descriptions v-if="selected" :column="1" border>
        <el-descriptions-item label="楼栋">{{ selected.building.name }}</el-descriptions-item><el-descriptions-item label="分类">{{ selected.category }}</el-descriptions-item><el-descriptions-item label="说明">{{ selected.description }}</el-descriptions-item><el-descriptions-item label="金额">{{ (selected.amount / 100).toFixed(2) }} 元</el-descriptions-item><el-descriptions-item label="来源或单据编号">{{ selected.sourceReference || '—' }}</el-descriptions-item><el-descriptions-item label="公区水电单据 ID">{{ selected.publicUtilityBillId || '—' }}</el-descriptions-item><el-descriptions-item label="记录人 ID">{{ selected.createdById }}</el-descriptions-item><el-descriptions-item label="状态">{{ selected.cancelledAt ? '已取消' : selected.payment ? '已付款' : '未付款' }}</el-descriptions-item><el-descriptions-item v-if="selected.payment || selected.cancelledAt" label="修改限制">已付款或已取消的记录不能更正或取消</el-descriptions-item><el-descriptions-item v-if="selected.payment" label="付款日期">{{ selected.payment.paidDate.slice(0, 10) }}</el-descriptions-item><el-descriptions-item v-if="selected.payment" label="付款凭证">{{ selected.payment.evidence }}</el-descriptions-item><el-descriptions-item v-if="selected.payment" label="付款记录人 ID">{{ selected.payment.recordedById }}</el-descriptions-item>
      </el-descriptions>
      <template #footer><el-button @click="detailsOpen = false">返回</el-button></template>
    </el-dialog>
    <el-dialog v-model="editOpen" title="更正未付款支出" width="min(520px, 95vw)"><el-form label-position="top" @submit.prevent="correct">
      <el-alert title="只能更正未付款记录；公区水电单据关联及楼栋不能更改。" type="info" :closable="false" />
      <el-form-item label="分类"><el-input v-model="edit.category" maxlength="80" /></el-form-item><el-form-item label="说明"><el-input v-model="edit.description" maxlength="500" /></el-form-item><el-form-item label="金额（分，整数）"><el-input-number v-model="edit.amount" :min="1" :max="2147483647" :precision="0" /></el-form-item><el-form-item label="来源或单据编号"><el-input v-model="edit.sourceReference" maxlength="500" /></el-form-item><el-form-item label="更正原因"><el-input v-model="edit.reason" maxlength="500" /></el-form-item><el-button @click="editOpen = false">返回</el-button><el-button native-type="submit" type="primary" :loading="saving">保存更正</el-button>
    </el-form></el-dialog>
    <el-dialog v-model="cancelOpen" title="取消未付款支出" width="min(520px, 95vw)"><el-form label-position="top" @submit.prevent="cancelExpense"><p>取消后不能付款，记录和公区单据关联将保留。</p><el-form-item label="取消原因"><el-input v-model="cancelReason" maxlength="500" /></el-form-item><el-button @click="cancelOpen = false">返回</el-button><el-button native-type="submit" type="danger" :loading="saving">确认取消支出</el-button></el-form></el-dialog>
    <el-dialog v-model="createOpen" title="新增支出" width="min(520px, 95vw)"><el-form label-position="top" @submit.prevent="create">
      <el-form-item label="楼栋"><el-select v-model="form.buildingId"><el-option v-for="b in buildings" :key="b.id" :value="b.id" :label="b.name" /></el-select></el-form-item>
      <el-form-item label="分类"><el-input v-model="form.category" maxlength="80" /></el-form-item><el-form-item label="说明"><el-input v-model="form.description" maxlength="500" /></el-form-item><el-form-item label="金额（分，整数）"><el-input-number v-model="form.amount" :min="1" :max="2147483647" :precision="0" /></el-form-item><el-form-item label="来源或单据编号"><el-input v-model="form.sourceReference" maxlength="500" /></el-form-item><el-form-item label="公区水电单据 ID（可选）"><el-input v-model="form.publicUtilityBillId" /></el-form-item><el-button native-type="submit" type="primary" :loading="saving">保存</el-button>
    </el-form></el-dialog>
    <el-dialog v-model="paymentOpen" title="记录已发生的付款" width="min(520px, 95vw)"><el-form label-position="top" @submit.prevent="pay"><p>金额：{{ ((selected?.amount || 0) / 100).toFixed(2) }} 元</p><p>付款日期不得晚于业务今天。</p><el-form-item label="付款日期"><el-date-picker v-model="payment.paidDate" value-format="YYYY-MM-DD" type="date" /></el-form-item><el-form-item label="付款凭证或流水编号"><el-input v-model="payment.evidence" maxlength="500" /></el-form-item><el-button native-type="submit" type="primary" :loading="saving">记录付款</el-button></el-form></el-dialog>
  </section>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { ElMessage } from 'element-plus';
import request from '@/utils/request';
import { canCreateExpense, canRecordPayment } from './validation';
interface Payment { paidDate: string; evidence: string; recordedById: string }
interface Expense { id: string; amount: number; building: { id: string; name: string }; category: string; description: string; sourceReference: string | null; publicUtilityBillId: string | null; createdById: string; version: number; cancelledAt: string | null; payment: Payment | null }
const rows = ref<Expense[]>([]); const buildings = ref<{id:string;name:string}[]>([]); const status = ref(''); const loading = ref(false); const saving = ref(false); const createOpen = ref(false); const paymentOpen = ref(false); const detailsOpen = ref(false); const editOpen = ref(false); const cancelOpen = ref(false); const cancelReason = ref(''); const selected = ref<Expense | null>(null);
const freshForm = () => ({ buildingId: '', category: '', description: '', amount: 1, sourceReference: '', publicUtilityBillId: '', requestKey: crypto.randomUUID() });
const edit = reactive({ category: '', description: '', amount: 1, sourceReference: '', reason: '' });
const form = reactive(freshForm()); const payment = reactive({ paidDate: '', evidence: '', requestKey: '' });
async function load() { loading.value = true; try { rows.value = await request.get('/expenses', { params: { status: status.value || undefined } }) as unknown as Expense[]; } finally { loading.value = false; } }
async function create() { if (saving.value) return; if (!canCreateExpense(form)) { ElMessage.warning('请填写楼栋、分类、说明和来源'); return; } saving.value = true; try { await request.post('/expenses', { ...form, sourceReference: form.sourceReference || undefined, publicUtilityBillId: form.publicUtilityBillId || undefined }); createOpen.value = false; Object.assign(form, freshForm()); await load(); } catch { /* 请求层已提示错误，保留表单供重试。 */ return; } finally { saving.value = false; } }
function openDetails(row: Expense) { selected.value = row; detailsOpen.value = true; }
function openEdit(row: Expense) { selected.value = row; Object.assign(edit, { category: row.category, description: row.description, amount: row.amount, sourceReference: row.sourceReference || '', reason: '' }); editOpen.value = true; }
function openCancel(row: Expense) { selected.value = row; cancelReason.value = ''; cancelOpen.value = true; }
async function correct() { if (saving.value) return; if (!selected.value || !edit.reason.trim() || !canCreateExpense({ ...edit, buildingId: selected.value.building.id, publicUtilityBillId: selected.value.publicUtilityBillId || '' })) { ElMessage.warning('请填写有效内容及更正原因'); return; } saving.value = true; try { await request.patch(`/expenses/${selected.value.id}`, { ...edit, sourceReference: edit.sourceReference || undefined, expectedVersion: selected.value.version }); editOpen.value = false; await load(); } catch { /* 请求层已提示错误，保留表单供重试。 */ return; } finally { saving.value = false; } }
async function cancelExpense() { if (saving.value) return; if (!selected.value || !cancelReason.value.trim()) { ElMessage.warning('请填写取消原因'); return; } saving.value = true; try { await request.post(`/expenses/${selected.value.id}/cancel`, { reason: cancelReason.value, expectedVersion: selected.value.version }); cancelOpen.value = false; await load(); } catch { /* 请求层已提示错误，保留表单供重试。 */ return; } finally { saving.value = false; } }
function openPayment(row: Expense) { selected.value = row; Object.assign(payment, { paidDate: '', evidence: '', requestKey: crypto.randomUUID() }); paymentOpen.value = true; }
async function pay() { if (saving.value) return; if (!selected.value || !canRecordPayment(payment)) { ElMessage.warning('请填写付款日期及凭证'); return; } saving.value = true; try { await request.post(`/expenses/${selected.value.id}/payments`, { ...payment, amount: selected.value.amount, expectedVersion: selected.value.version }); paymentOpen.value = false; await load(); } catch { /* 请求层已提示错误，保留表单供重试。 */ return; } finally { saving.value = false; } }
onMounted(async () => { buildings.value = await request.get('/expenses/buildings') as unknown as typeof buildings.value; await load(); });
</script>
<style scoped>.toolbar { display:flex; justify-content:space-between; gap:1rem; margin:1rem 0; }.toolbar .el-select { max-width:200px; }</style>
